    normalized = re.sub(r"\s+", " ", text).strip()
    # If the normalized text fits within the limit, return it unchanged
    if len(normalized) <= limit:
        return normalized
    # For limits 0 to 3, return that many dots (limit 0 yields empty string)
    if limit <= 3:
        return "." * limit
    # Otherwise truncate to (limit - 3) characters, strip trailing spaces, and append ellipsis
    trunc_len = limit - 3
    return normalized[:trunc_len].rstrip() + "..."

